struct vector4d {
    float x, y, z, w;
};

struct vector3d {
    float x, y, z;
    vector3d(float ax, float ay, float az) : x(ax), y(ay), z(az) {}
};

struct matrix4x4 {
    vector4d x, y, z, w;
};

struct nglQuad {
    char data[0x7c];
};

extern "C" void adjustCoords(float &, float &)
    __asm__("adjustCoords__H1Zf_RX01T0_v");
extern "C" void nglSetQuadRect(nglQuad *, float, float, float, float)
    __asm__("nglSetQuadRect__FP7nglQuadffff");
extern "C" void nglSetQuadColor(nglQuad *, unsigned int)
    __asm__("nglSetQuadColor__FP7nglQuadUi");
extern "C" void nglSetQuadUV(nglQuad *, float, float, float, float)
    __asm__("nglSetQuadUV__FP7nglQuadffff");
extern "C" void nglSetQuadZ(nglQuad *, float)
    __asm__("nglSetQuadZ__FP7nglQuadf");
extern "C" void nglSetQuadMapFlags(nglQuad *, unsigned int)
    __asm__("nglSetQuadMapFlags__FP7nglQuadUi");

inline vector3d xform3d_1_homog(const matrix4x4 &m44, const vector3d &sv)
{
    float w;
    w = m44.x.w * sv.x + m44.y.w * sv.y + m44.z.w * sv.z + m44.w.w;
    if (w)
        w = 1.0f / w;
    vector3d result(0.0f, 0.0f, 0.0f);
    result.x = (m44.x.x * sv.x + m44.y.x * sv.y + m44.z.x * sv.z + m44.w.x) * w;
    result.y = (m44.x.y * sv.x + m44.y.y * sv.y + m44.z.y * sv.z + m44.w.y) * w;
    result.z = (m44.x.z * sv.x + m44.y.z * sv.y + m44.z.z * sv.z + m44.w.z) * w;
    return result;
}

inline int FTOI(float input)
{
    return (int)input;
}

class PanelQuad {
    char padding0[0x1c];
    nglQuad quad;
    float r, g, b, a;
    float x1, y1, x2, y2;
    float width, height;
    float width_a, height_a;
    char padding1[0x8];
    matrix4x4 matrix;
    char padding2[0x6c];
    float z;
    float u1, v1, u2, v2;

public:
    virtual void Init(float xa, float ya, float xb, float yb,
                      float r1, float g1, float b1, float a1,
                      float ua, float va, float ub, float vb,
                      float z1, matrix4x4 obj);
};

void PanelQuad::Init(float xa, float ya, float xb, float yb,
                     float r1, float g1, float b1, float a1,
                     float ua, float va, float ub, float vb,
                     float z1, matrix4x4 obj)
{
    r = r1; g = g1; b = b1; a = a1;
    u1 = ua; v1 = va; u2 = ub; v2 = vb;
    matrix = obj;
    vector3d vec1 = xform3d_1_homog(matrix, vector3d(xa, ya, z1));
    vector3d vec2 = xform3d_1_homog(matrix, vector3d(xb, yb, z1));
    x1 = vec1.x; x2 = vec2.x; y1 = vec1.y; y2 = vec2.y;
    z = vec1.z;
    width_a = x2-x1;
    height_a = y2-y1;
    adjustCoords(x1, y1);
    adjustCoords(x2, y2);
    width = x2-x1;
    height = y2-y1;

    nglSetQuadRect(&quad, x1, y1, x2, y2);
    nglSetQuadColor(&quad,
        ((FTOI(r*255.0f)+1)>>1) |
        (((FTOI(g*256.0f)+1)>>1) << 8) |
        (((FTOI(b*255.0f)+1)>>1) << 16) |
        (((FTOI(a*255.0f)+1)>>1) << 24));
    nglSetQuadUV(&quad, u1, v1, u2, v2);
    nglSetQuadZ(&quad, z);
    nglSetQuadMapFlags(&quad, 0x32);
}
